class Solution:
    def shortestFix(self, s: str) -> int:
        n, q = len(s), len(s) // 4
        total = {c: s.count(c) for c in "SATB"}
        if all(v == q for v in total.values()):
            return 0
        best = n
        for i in range(n):
            out = dict(total)
            for j in range(i, n):
                out[s[j]] -= 1
                if all(v <= q for v in out.values()):
                    best = min(best, j - i + 1)
                    break
        return best

