class Solution {
    public int shortestFix(String s) {
        int n = s.length(), q = n / 4, best = n;
        int[] total = new int[128];
        for (char c : s.toCharArray()) total[c]++;
        if (total['S'] == q && total['A'] == q && total['T'] == q) return 0;
        for (int i = 0; i < n; i++) {
            int[] out = total.clone();
            for (int j = i; j < n; j++) {
                out[s.charAt(j)]--;
                if (out['S'] <= q && out['A'] <= q && out['T'] <= q && out['B'] <= q) { best = Math.min(best, j - i + 1); break; }
            }
        }
        return best;
    }
}

