        out = {c: s.count(c) for c in "SATB"}
        if all(v == q for v in out.values()):
            return 0
        best, left = n, 0
        for i, c in enumerate(s):
            out[c] -= 1
            while all(v <= q for v in out.values()):
                best = min(best, i - left + 1)
                out[s[left]] += 1
